toolScript:
import {
            FaceLandmarker,
            FilesetResolver
        } from "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3";
        const video = document.getElementById('scanner-video');
        const canvas = document.getElementById('overlay-canvas');
        const ctx = canvas.getContext('2d');
        const statusText = document.getElementById('status-text');
        const faceGuide = document.getElementById('face-guide');
        const resultBadge = document.getElementById('gaze-result');
        const liveIndicator = document.getElementById('live-indicator');
        const gazeDot = document.getElementById('gaze-dot');
        let faceLandmarker;
        let runningMode = "VIDEO";
        let stream = null;
        let lastVideoTime = -1;
        let results = undefined;
        let trackingActive = false;
        // Session Metrics
        let totalFrames = 0;
        let contactFrames = 0;
        let blinkCount = 0;
        let lastBlinkState = false; // true = eyes closed
        let startTime = 0;
        function log(msg, type = 'default') {
            const term = document.getElementById('terminal');
            const content = document.getElementById('terminal-content');
            const line = document.createElement('div');
            const time = new Date().toLocaleTimeString().split(' ')[0];
            const colorClass = type === 'success' ? 'text-emerald-400' : (type === 'error' ? 'text-red-500' : 'text-slate-400');
            line.innerHTML = `<span class="opacity-30">[${time}]</span> <span class="${colorClass}">${msg}</span>`;
            content.appendChild(line);
            term.scrollTop = term.scrollHeight;
        }
        async function createFaceLandmarker() {
            log("Initializing MediaPipe Iris Model...");
            try {
                const filesetResolver = await FilesetResolver.forVisionTasks(
                    "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm"
                );
                faceLandmarker = await FaceLandmarker.createFromOptions(filesetResolver, {
                    baseOptions: {
                        modelAssetPath: `https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task`,
                        delegate: "GPU"
                    },
                    outputFaceBlendshapes: true,
                    runningMode: runningMode,
                    numFaces: 1
                });
                log("Vision Core Ready. Tracking Engine Standby.", "success");
            } catch (e) {
                log("LOAD ERROR: Vision nodes failed to sync.", "error");
            }
        }
        createFaceLandmarker();
        window.startWebcam = async function () {
            try {
                log("Requesting optical stream...");
                stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } });
                video.srcObject = stream;
                // Wait for video data to load to prevent 0x0 size errors
                video.onloadeddata = () => {
                    video.style.display = 'block';
                    statusText.style.display = 'none';
                    faceGuide.style.display = 'block';
                    liveIndicator.style.display = 'block';
                    resultBadge.style.display = 'block';
                    trackingActive = true;
                    startTime = Date.now();
                    resetMetrics();
                    log("Stream active. Gaze analysis engaged.", "success");
                    document.getElementById('tracking-status').innerText = "ACTIVE";
                    document.getElementById('tracking-status').className = "text-emerald-500 font-bold uppercase";
                    predictWebcam();
                };
            } catch (err) {
                console.error(err);
                log("HARDWARE ERROR: Permission denied.", "error");
            }
        };
        function resetMetrics() {
            totalFrames = 0;
            contactFrames = 0;
            blinkCount = 0;
            startTime = Date.now();
            updateStats(true);
        }
        window.resetSession = function () {
            resetMetrics();
            log("Session metrics cleared.");
        };
        async function predictWebcam() {
            if (!trackingActive) return;
            // Ensure video has valid dimensions
            if (video.videoWidth === 0 || video.videoHeight === 0) {
                requestAnimationFrame(predictWebcam);
                return;
            }
            let startTimeMs = performance.now();
            if (lastVideoTime !== video.currentTime) {
                lastVideoTime = video.currentTime;
                if (faceLandmarker) {
                    results = faceLandmarker.detectForVideo(video, startTimeMs);
                }
            }
            canvas.width = video.clientWidth;
            canvas.height = video.clientHeight;
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            if (results && results.faceLandmarks && results.faceLandmarks.length > 0) {
                const landmarks = results.faceLandmarks[0];
                const blendshapes = results.faceBlendshapes[0];
                document.getElementById('points-val').innerText = "478";
                // Draw eyes only
                drawEyeOverlay(landmarks);
                // Process Logic
                processGaze(landmarks, blendshapes);
            } else {
                if (trackingActive) {
                    // Draw searching rect
                    ctx.strokeStyle = "rgba(255,255,255,0.2)";
                    ctx.lineWidth = 2;
                    ctx.strokeRect(canvas.width / 2 - 100, canvas.height / 2 - 100, 200, 200);
                    ctx.font = "12px monospace";
                    ctx.fillStyle = "white";
                    ctx.fillText("SEARCHING...", canvas.width / 2 - 35, canvas.height / 2);
                }
            }
            requestAnimationFrame(predictWebcam);
        }
        function drawEyeOverlay(landmarks) {
            // Right Eye Iris: 473 (center), 474-477 (circumference)
            // Left Eye Iris: 468 (center), 469-472 (circumference)
            const rightIris = landmarks[473];
            const leftIris = landmarks[468];
            ctx.fillStyle = 'rgba(52, 211, 153, 0.4)'; // Emerald
            // Draw Right Iris
            ctx.beginPath();
            ctx.arc(rightIris.x * canvas.width, rightIris.y * canvas.height, 4, 0, 2 * Math.PI);
            ctx.fill();
            // Draw Left Iris
            ctx.beginPath();
            ctx.arc(leftIris.x * canvas.width, leftIris.y * canvas.height, 4, 0, 2 * Math.PI);
            ctx.fill();
        }
        function processGaze(landmarks, blendshapes) {
            totalFrames++;
            // 1. Blink Detection using Blendshapes
            // eyeBlinkLeft, eyeBlinkRight
            const bs = {};
            blendshapes.categories.forEach(c => bs[c.categoryName] = c.score);
            const isBlinking = (bs.eyeBlinkLeft > 0.5 || bs.eyeBlinkRight > 0.5);
            // Count blinks (rising edge)
            if (isBlinking && !lastBlinkState) {
                blinkCount++;
            }
            lastBlinkState = isBlinking;
            // 2. Gaze Vector Calculation (Simplified Horizontal/Vertical Ratio)
            // Need Eye Corners. 
            // Left Eye: 33 (inner), 133 (outer). Iris: 468.
            // Right Eye: 362 (inner), 263 (outer). Iris: 473.
            const lInner = landmarks[33];
            const lOuter = landmarks[133];
            const lIris = landmarks[468];
            // Horizontal ratio (0 = inner corner, 1 = outer corner)
            // For left eye, inner is right-most in image (if mirrored? No, landmarks are normalized). 
            // x increases left-to-right.
            // Distances
            const dLTotal = lOuter.x - lInner.x; // width of eye
            const dLIris = lIris.x - lInner.x;   // iris pos relative to inner
            const lRatio = dLIris / dLTotal;
            // 3. Determine Direction
            // Center is roughly 0.5? Usually iris is centered around 0.45-0.55 depending on face rotation
            let direction = "CENTER";
            let stability = 100;
            // Looking Left (User's left, Screen Right) -> Ratio increases?
            // Test logic: 
            // If tracking yourself: looking left moves iris to left of eye socket.
            // Note: Camera might be mirrored. 
            // Heuristic for "Looking at Camera":
            // Blendshape "eyeLookUp", "eyeLookDown", "eyeLookIn", "eyeLookOut" are better than raw math
            let isContact = true;
            if (bs.eyeLookUpLeft > 0.2 || bs.eyeLookUpRight > 0.2) { direction = "UP"; isContact = false; }
            else if (bs.eyeLookDownLeft > 0.2 || bs.eyeLookDownRight > 0.2) { direction = "DOWN (READING)"; isContact = false; }
            else if (bs.eyeLookOutLeft > 0.2 && bs.eyeLookOutRight > 0.2) { direction = "SIDE"; isContact = false; } // Divergent?
            else if (bs.eyeLookInLeft > 0.2 && bs.eyeLookInRight > 0.2) { direction = "CROSSED"; isContact = false; }
            else if (Math.abs(lRatio - 0.5) > 0.15) { direction = "SIDE"; isContact = false; } // Fallback math
            if (isContact && !isBlinking) contactFrames++;
            // 4. Head Tilt
            const dy = landmarks[263].y - landmarks[33].y;
            const dx = landmarks[263].x - landmarks[33].x;
            const angle = Math.atan2(dy, dx) * (180 / Math.PI);
            // Update UI
            document.getElementById('dir-val').innerText = direction;
            if (direction === "CENTER") document.getElementById('dir-val').style.color = "#34d399";
            else document.getElementById('dir-val').style.color = "#fbbf24";
            document.getElementById('tilt-val').innerText = `${angle.toFixed(1)}°`;
            updateStats();
        }
        function updateStats(reset = false) {
            if (reset) {
                document.getElementById('score-val').innerText = "--%";
                document.getElementById('blink-val').innerText = "--/min";
                document.getElementById('stability-val').innerText = "--%";
                return;
            }
            // Score
            const score = totalFrames > 0 ? ((contactFrames / totalFrames) * 100).toFixed(0) : 0;
            document.getElementById('score-val').innerText = `${score}%`;
            // BPM
            const minutes = (Date.now() - startTime) / 60000;
            const bpm = minutes > 0 ? (blinkCount / minutes).toFixed(1) : 0;
            document.getElementById('blink-val').innerText = `${bpm}/min`;
            // Stability (Simulated inverse of head movement speed, here just placeholder high value if center)
            const stab = document.getElementById('dir-val').innerText === "CENTER" ? "98%" : "LOW";
            document.getElementById('stability-val').innerText = stab;
        }

        log("Lens Focus Trainer Node (Iris Tracking) initialized.");
